}

private int dfs(int node, List<List<Integer>> graph, boolean[] hasApple, boolean[] visited, int time) {
    visited[node] = true;
    int totalTime = 0;
    for (int neighbor : graph.get(node)) {
        if (!visited[neighbor]) {
            totalTime += dfs(neighbor, graph, hasApple, visited, time + 1);
        }
    }
    if (hasApple[node] || totalTime > 0) {
        totalTime += 2;
    }
    return totalTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    int[] charCount = new int[26];
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    int i = 0;
    while (i < s.length()) {
        // Pick the smallest character
        for (int j = 0; j < 26; j++) {
            if (charCount[j] > 0) {
                result.append((char) ('a' + j));
                charCount[j]--;
                i++;
                break;
            }
        }

        // Pick the largest character
        for (int j = 25; j >= 0; j--) {
            if (charCount[j] > 0) {
                result.append((char) ('a' + j));
                charCount[j]--;
                i++;
                break;
            }
        }
    }

    return result.toString();
}

