public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int m = (1 << k);
    boolean[] seen = new boolean[m];
    for (int i = 0; i <= n - k; i++) {
        int num = Integer.parseInt(s.substring(i, i + k), 2);
        if (seen[num]) {
            return false;
        }
        seen[num] = true;
    }
    return true;
}

