public int maxUniqueSplit(String s) {
    int maxUnique = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (isUnique(prefix)) {
            maxUnique++;
            if (i == s.length()) {
                break;
            }
            maxUnique += maxUniqueSplit(s.substring(i));
        }
    }
    return maxUnique;
}

private boolean isUnique(String str) {
