    int maxArea = 0;
    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];

    // Find the nearest smaller element to the left for each bar
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            leftSmaller[i] = -1;
        } else {
            leftSmaller[i] = stack.peek();
        }
        stack.push(i);
    }

    // Find the nearest smaller element to the right for each bar
    stack.clear();
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            rightSmaller[i] = heights.length;
        } else {
            rightSmaller[i] = stack.peek();
        }
        stack.push(i);
    }

    // Calculate the area of each bar and find the maximum
    for (int i = 0; i < heights.length; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        int area = heights[i] * width;
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            result[index++] = mat[i][j];
        }
    }

    for (int i = 1; i < cols; i++) {
        for (int j = rows - 1; j >= 0; j--) {
            if (j + i < rows) {
                result[index++] = mat[j + i][i];
            }
        }
    }

    for (int i = 1; i < rows; i++) {
        for (int j = 0; j < cols - 1; j++) {
            if (j + i < cols) {
                result[index++] = mat[i][j + i];
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 9) {
        return -1; // No possible rearrangement greater than n
    }

    int[] digits = new int[10];
    int count = 0;
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
        count++;
    }

    int smallest = 0;
    for (int i = 0; i < 10; i++) {
        if (digits[i] > 0) {
            smallest = i;
            break;
        }
    }

    if (smallest == 0) {
        return -1; // No valid rearrangement
    }

    digits[smallest]--;
    for (int i = 9; i >= 0; i--) {
        if (digits[i] > 0) {
            smallest = i;
            break;
        }
    }

    int temp = smallest;
    smallest = digits[smallest];
    digits[smallest] = temp;

    for (int i = 0; i < count; i++) {
        if (i == smallest) {
            continue;
        }
        smallest = digits[smallest];
        digits[smallest] = temp;
        temp = smallest;
    }

    int result = 0;
    for (int i = 0; i < count; i++) {
        result = result * 10 + digits[i];
    }

    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    if (n % 2 == 0) {
        return result;
    }
    int mid = n / 2;
    for (int i = 0; i < 10; i++) {
        String prefix = String.valueOf(i).repeat(mid);
        String suffix = new StringBuilder(prefix).reverse().toString();
        result.add(prefix + suffix);
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if the points form a triangle
    if (x1 == x2 || x1 == x3 || x2 == x3) {
        return false;
    }

    // Calculate the area of the triangle using the determinant method
    int area = (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2;

    // If the area is zero, the points are collinear and do not form a triangle
    if (area == 0) {
        return false;
    }

    return true;
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2, nextMultipleOf3 = 3, nextMultipleOf5 = 5;

    for (int i = 1; i < n; i++) {
        int min = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = min;

        if (min == nextMultipleOf2) {
            i2++;
            nextMultipleOf2 = uglyNumbers[i2] * 2;
        }
        if (min == nextMultipleOf3) {
            i3++;
            nextMultipleOf3 = uglyNumbers[i3] * 3;
        }
        if (min == nextMultipleOf5) {
            i5++;
            nextMultipleOf5 = uglyNumbers[i5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int maxEnergy = 0;
    int currentEnergy = 1;
    char prevChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == prevChar) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
        prevChar = s.charAt(i);
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);
    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        dfs(current * 10 + i, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    for (int num : nums) {
        uniqueElements.add(num);
    }
    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    String[] words = s.split(" ");
    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        reversedWord.reverse();
        result.append(reversedWord).append(" ");
    }
    return result.toString().trim();
}
